function sortedStr(str, i) {	
 	  let obj = {};
    let arr = String(str).split('&');
    arr.forEach(item => {
        let [key, value] = item.split('=');
        obj[key] = value;
      });
     var result = Object.keys(obj).sort();
    if(/platform=0/.test(str)){
     result = result
     .map(key=>key + "=" + obj[key]).join("&");
    }else{
     	result = result
     	.map(key=> obj[key]).join("");
    }    
      return result
}

function Token() {	
 	  const { java, source } = this;
    let origin = "https://t.shuqi.com";  	 
   	var token = java.get(origin,{}).cookies()
    .toString().match(/shuqi_token=([^,]*)/)[1];
    var head = {
    		"authorization": "Bearer "+token
    	}; 	
    token = source.putLoginHeader(
    	JSON.stringify(head));
      return token
}

function GetUrl(path, params, sourceUrl) {
 	  const { java, source } = this;
 	  let sourceUrl = sourceUrl || "https://ocean.shuqireader.com";
    var v = source.getVariable();
    try{
    var userId = JSON.parse(v)[0].uid[0].userId;
  }catch(e){
  	  var userId = '12345678';
  	}

    var t = Date.now();
    var time = ~~(t / 1e3);

    var gateway = "sq_h5_gateway";
    var params0 = "sqSv=1.0";
   	 var params1 = `user_id=${userId}&timestamp=${time}`;



   	 if (/info/.test(path)) {
   	  var skey = "37e81a9d8f02596e1b895d07c171d5c9";
   	  var params = params1 + "&" + params;	  
   	  var sign = java.md5Encode(sortedStr(params) + skey);    
