// SQ_COMMENT_API_V1_BEGIN
var SQ_COMMENT_API_BASE = "https://shuqi.aadcn.cn";
var SQ_COMMENT_API_KEY = "tongrenshuqi134679";
var _sqRenderExtKey = "";
var _sqRenderExtValue = null;
var _sqMetaMapCache = null;
var _sqShortMapCache = null;

function sqSource() {
    try { if (this && this.source) return this.source; } catch(e) {}
    try { if (typeof source !== "undefined") return source; } catch(e2) {}
    return null;
}

function sqJava() {
    try { if (this && this.java) return this.java; } catch(e) {}
    try { if (typeof java !== "undefined") return java; } catch(e2) {}
    return null;
}

function sqLoginValue(key, defaultValue) {
    try {
        var s = sqSource.call(this);
        var map = s && s.getLoginInfoMap ? s.getLoginInfoMap() : null;
        var value = map && (map.get ? map.get(key) : map[key]);
        if (value !== null && value !== undefined && String(value).trim() !== "") return String(value);
    } catch(e) {}
    return defaultValue == null ? "" : String(defaultValue);
}

function sqToggle(key, defaultValue) {
    var value = sqLoginValue.call(this, key, "");
    if (!value) return !!defaultValue;
    value = String(value).trim().toLowerCase();
    return value === "✅" || value === "1" || value === "true" || value === "开" || value === "开启";
}

function sqCommentConfig() {
    var style = sqLoginValue.call(this, "◎ 模板", "起点");
    var templateKey = String(style).replace("样式", "◎ 气泡");
    return {
        paragraph: sqToggle.call(this, "段评开关", false),
        chapter: sqToggle.call(this, "章评开关", false),
        color: sqLoginValue.call(this, "段评气泡颜色", "#666666"),
        colorSplit: sqToggle.call(this, "段评分色", false),
        splitColor: sqLoginValue.call(this, "分色气泡颜色", "#e23b3b"),
        splitCount: Number(sqLoginValue.call(this, "分色评论数", "45")) || 45,
        hotColor: sqLoginValue.call(this, "热门气泡颜色", "#f06060"),
        theme: sqLoginValue.call(this, "评论主题", "自动"),
        height: sqLoginValue.call(this, "评论窗口高度", "80"),
        bubbleStyle: style,
        bubbleSize: sqLoginValue.call(this, "◎ 大小", "text"),
        bubbleTemplate: sqLoginValue.call(this, templateKey, "")
    };
}

function sqApiKey() {
    return sqLoginValue.call(this, "书旗评论 API Key", "") || SQ_COMMENT_API_KEY;
}

function sqPost(path, body) {
    var j = sqJava.call(this);
    if (!j) return { ok: false, error: "java unavailable" };
    var payload = body || {};
    payload.apiKey = sqApiKey.call(this);
    var option = {
        method: "POST",
        body: JSON.stringify(payload),
        headers: { "Content-Type": "application/json", "Accept": "application/json" }
    };
    try {
        var raw = j.ajax(SQ_COMMENT_API_BASE + path + "," + JSON.stringify(option));
        var text = String(raw || "{}").replace(/^\uFEFF/, "").trim();
        return JSON.parse(text || "{}");
    } catch(e) {
        try { j.log("书旗评论接口请求失败 " + path + ": " + e); } catch(_) {}
        return { ok: false, error: String(e) };
    }
}

function sqList(value) {
    if (!value) return [];
    if (Array.isArray(value)) return value;
    if (value.size && value.get) {
        var result = [];
        for (var i = 0; i < value.size(); i++) result.push(value.get(i));
        return result;
    }
    return [];
}

function sqRenderExt(bookId, chapterId) {
    var key = String(bookId || "") + ":" + String(chapterId || "");
    if (key && key === _sqRenderExtKey && _sqRenderExtValue) return _sqRenderExtValue;
    var response = sqPost.call(this, "/v1/reader/render-ext", {
        bookId: String(bookId || ""),
        chapterId: String(chapterId || "")
    });
    if (response && response.ok) {
        _sqRenderExtKey = key;
        _sqRenderExtValue = response;
    }
    return response || { ok: false };
}

function sqParagraphList(response) {
    try {
        var outer = response && response.data || {};
        var data = outer.data || outer.Data || {};
        var ext = data.bookChapterExtInfo || data.BookChapterExtInfo || {};
        return sqList(ext.paragraphList || ext.ParagraphList);
    } catch(e) {
        return [];
    }
}

function sqCommentList(response) {
    try {
        var outer = response && response.data || {};
        var data = outer.data || outer.Data || {};
        return sqList(data.commentList || data.CommentList);
    } catch(e) {
        return [];
    }
}

function sqReadMap(key, cacheName) {
    if (cacheName === "meta" && _sqMetaMapCache !== null) return _sqMetaMapCache;
    if (cacheName === "short" && _sqShortMapCache !== null) return _sqShortMapCache;
    var map = {};
    try {
        var j = sqJava.call(this);
        var raw = j && j.get ? j.get(key) : "";
        if (raw) map = JSON.parse(String(raw)) || {};
    } catch(e) { map = {}; }
