@js:
(function () {
  var raw = String(src || "").trim();
  if (!raw) return "获取正文失败：响应为空";
  if (/^data:text\/plain;base64,/i.test(raw)) {
    try {
      var dataMatch = raw.match(/^data:text\/plain;base64,([^#,\s]+)/i);
      if (dataMatch && dataMatch[1]) raw = String(java.base64Decode(dataMatch[1]) || "").trim();
    } catch (eDataUrl) { return "获取正文失败：data URL 解码失败"; }
  }
  var requestUrl = "";
  var responseText = raw;
  if (/^https?:\/\//i.test(raw)) {
    requestUrl = raw;
    try { responseText = String(java.ajax(requestUrl) || ""); }
    catch (eRequest) { return "获取正文失败：章节请求失败"; }
  }
  var obj;
  try { obj = JSON.parse(responseText || "{}"); }
  catch (eParse) { return "获取正文失败：响应格式错误"; }
  var enc = "";
  if (obj.message == "success" && obj.ChapterContent) {
    enc = obj.ChapterContent;
  } else {
    var shortUrl = "";
    try {
      var lookupUrl = requestUrl || String(baseUrl || "");
      var optionAt = lookupUrl.lastIndexOf(",{");
      if (optionAt > 0) lookupUrl = lookupUrl.substring(0, optionAt);
      shortUrl = sqLookupMap(sqGetShortMap(this), lookupUrl);
      if (!shortUrl && java && java.get) {
        shortUrl = String(java.get("sqShort@" + lookupUrl) || java.get("shortUrl") || "");
      }
    } catch (eShortMap) {
      try { shortUrl = String(java.get("shortUrl") || ""); } catch (eLegacy) {}
    }
    if (!shortUrl) return "付费章节地址缺失，请刷新目录";
    try {
      var shortObj = JSON.parse(String(java.ajax(shortUrl) || "{}"));
      enc = shortObj.ChapterContent || "";
    } catch (eShort) { return "付费章节加载失败"; }
  }
  if (!enc) return "章节内容为空";
  function p(e) {
    return String(e || "").split("").map(function (ch) {
      return ch.match(/[A-Za-z]/)
        ? ((c = Math.floor(ch.charCodeAt(0) / 97),
           k = (ch.toLowerCase().charCodeAt(0) - 83) % 26 || 26,
           String.fromCharCode(k + (0 == c ? 64 : 96))))
        : ch;
    }).join("");
  }
  var text = java.base64Decode(p(enc));
  var meta = sqGetChapterMeta.call(this, baseUrl);
  if (!meta && requestUrl) meta = sqGetChapterMeta.call(this, requestUrl);
  if (meta && meta.bookId && meta.chapterId) {
    var chapterQuote = "";
    try { if (typeof chapter !== "undefined" && chapter) chapterQuote = String(chapter.title || chapter.chapterName || ""); } catch (eChapterQuote) {}
    text = sqDecorateContent.call(this, text, meta.bookId, meta.chapterId, chapterQuote);
  }
  return text;
})();

